from pathlib import Path
import re, shutil, time
ROOT=Path.cwd(); PUBLIC=ROOT/"public"
control=PUBLIC/"control.js"; settings=PUBLIC/"settings.js"; css=PUBLIC/"settings.css"
for p in (control,settings,css):
    if not p.exists(): raise SystemExit(f"Missing {p}. Run from C:\\GuardianWebClean")
backup=ROOT/f"_backup_settings_map_{time.strftime('%Y%m%d_%H%M%S')}"; backup.mkdir()
for p in (control,settings,css): shutil.copy2(p,backup/p.name)

c=control.read_text(encoding="utf-8")
c=c.replace(' · Drag to position">','">')
start=c.find('overlay.querySelectorAll("[data-map-station]").forEach')
end=c.find('overlay.querySelectorAll("[data-map-call]").forEach',start)
if start<0 or end<0: raise SystemExit("Could not find Control station drag block.")
replacement='overlay.querySelectorAll("[data-map-station]").forEach(b=>{\n   b.addEventListener("click",()=>showStation(b.dataset.mapStation));\n });\n '
c=c[:start]+replacement+c[end:]
control.write_text(c,encoding="utf-8")

s=settings.read_text(encoding="utf-8")
start=s.find("function renderMap(){"); end=s.find("function renderConfig(){",start)
if start<0 or end<0: raise SystemExit("Could not find Settings map renderer.")
new_map='async function renderMap(){\n  $("content").innerHTML=`<div class="card"><div class="settingsMapHead"><div><h3>Station Map Editor</h3><p>Drag stations here. Station markers on the Control Centre map are read-only.</p></div><div><button id="saveMap">SAVE MAP POSITIONS</button></div></div><div id="stationMapStatus" class="mapHint">Loading Guardian operational map…</div><div id="stationMap" class="mapCanvas"></div></div>`;\n  const canvas=$("stationMap"),hint=$("stationMapStatus");\n  let live={}; try{live=await fetch("/api/state",{cache:"no-store"}).then(r=>r.ok?r.json():{});}catch(_){}\n  config.map||={stations:{}}; config.map.stations||={};\n  const defaults=[\n    {name:"Berwick Fire Station",postal:"4011"},{name:"Coldstream Fire Station",postal:"7287"},\n    {name:"Crewe Toll Fire Station",postal:"7039"},{name:"McDonald Road Fire Station",postal:"7326"},\n    {name:"Musselburgh Fire Station",postal:"9092"},{name:"Sighthill Fire Station",postal:"7246"}\n  ];\n  const byName=new Map(defaults.map(x=>[x.name.toLowerCase(),x]));\n  (config.stations||[]).forEach(x=>{if(x?.name)byName.set(String(x.name).toLowerCase(),{...byName.get(String(x.name).toLowerCase()),...x})});\n  Object.values(live.callSignStations||{}).forEach(name=>{name=String(name||"").trim();if(name&&!byName.has(name.toLowerCase()))byName.set(name.toLowerCase(),{name,postal:""})});\n  const stations=[...byName.values()], saved=live.stationMapPositions||{};\n  const rows=await fetch("/control/assets/postals.json",{cache:"no-store"}).then(r=>r.ok?r.json():[]).catch(()=>[]);\n  const entries=Array.isArray(rows)?rows:Object.values(rows||{});\n  const pi=new Map(entries.map(p=>[String(p.code||p.postal||""),{x:Number(p.x),y:Number(p.y)}]));\n  const B={minX:-3427.08984375,maxX:3751.1640625,minY:-3779.6020520333,maxY:6990.4082043770};\n  const world=p=>({x:((p.x-B.minX)/(B.maxX-B.minX))*100,y:((B.maxY-p.y)/(B.maxY-B.minY))*100});\n  const pending=new Map();\n  stations.forEach((st,i)=>{\n    const key=String(st.name).trim().toLowerCase(), lp=saved[key], cp=config.map.stations[st.name], pp=pi.get(String(st.postal||""));\n    let pos=lp&&Number.isFinite(+lp.mapXPercent)&&Number.isFinite(+lp.mapYPercent)?{x:+lp.mapXPercent,y:+lp.mapYPercent}:cp&&Number.isFinite(+cp.x)&&Number.isFinite(+cp.y)?{x:+cp.x,y:+cp.y}:pp?world(pp):{x:45+(i%4)*4,y:45+Math.floor(i/4)*4};\n    const m=document.createElement("button");m.className="stationMarker";m.type="button";\n    m.style.left=pos.x+"%";m.style.top=pos.y+"%";m.title=`${st.name}${st.postal?` · Postal ${st.postal}`:""} · Drag to position`;\n    m.innerHTML=`<span>FS</span><b>${st.name}</b>`;\n    let dragging=false,pid=null;\n    m.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();dragging=true;pid=e.pointerId;m.classList.add("dragging");m.setPointerCapture?.(pid)};\n    m.onpointermove=e=>{if(!dragging)return;const r=canvas.getBoundingClientRect(),x=Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100)),y=Math.max(0,Math.min(100,(e.clientY-r.top)/r.height*100));m.style.left=x+"%";m.style.top=y+"%";pending.set(st.name,{x,y});hint.textContent=`Unsaved position: ${st.name}`;hint.classList.add("dirty")};\n    m.onpointerup=()=>{dragging=false;m.classList.remove("dragging")};m.onpointercancel=m.onpointerup;canvas.appendChild(m);\n  });\n  $("saveMap").onclick=async()=>{\n    if(!pending.size){hint.textContent="No station positions changed.";return}\n    const btn=$("saveMap");btn.disabled=true;\n    try{\n      for(const [stationName,p] of pending){\n        const r=await fetch("/api/command",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"setStationMapPosition",data:{stationName,mapXPercent:p.x,mapYPercent:p.y}})});\n        if(!r.ok)throw new Error(await r.text());\n        config.map.stations[stationName]={x:p.x,y:p.y};\n      }\n      await api("/api/admin/config",{method:"POST",body:JSON.stringify({config})});\n      pending.clear();hint.textContent="Saved. Control Centre now uses these station positions.";hint.className="mapHint saved";\n    }catch(e){hint.textContent="Save failed: "+e.message;hint.className="mapHint error"}finally{btn.disabled=false}\n  };\n}\n\n'
s=s[:start]+new_map+s[end:]; settings.write_text(s,encoding="utf-8")

cs=css.read_text(encoding="utf-8")
addon="\n/* Guardian Settings Station Map v1 */\n.settingsMapHead{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:10px}\n.settingsMapHead p{margin:0;color:#8eacbd;font-size:12px}.mapHint{padding:9px 11px;margin:8px 0 10px;border:1px solid #29495b;border-radius:5px;color:#8eacbd;font-size:11px}\n.mapHint.dirty{color:#f0c86c;border-color:#6b5726}.mapHint.saved{color:#67d59a;border-color:#245b40}\n.mapCanvas{position:relative;width:100%;aspect-ratio:1.7777778;min-height:620px;background:#0a1b24 url('/control/assets/postal_map.png') center/100% 100% no-repeat;border:1px solid #315365;border-radius:8px;overflow:hidden;touch-action:none}\n.stationMarker{position:absolute;transform:translate(-50%,-50%);width:32px;height:32px;border-radius:50%;background:#1f9d68;border:2px solid #fff;color:#fff;font-size:9px;display:grid;place-items:center;cursor:grab;z-index:3;padding:0;overflow:visible}\n.stationMarker.dragging{cursor:grabbing;z-index:10}.stationMarker span{font-weight:900}.stationMarker b{position:absolute;left:38px;top:50%;transform:translateY(-50%);white-space:nowrap;background:#071923dd;border:1px solid #315365;border-radius:4px;padding:4px 6px;color:#eaf7ff;font-size:9px;pointer-events:none}\n"
if "Guardian Settings Station Map v1" not in cs: cs+="\n"+addon
css.write_text(cs,encoding="utf-8")
print("Installed Guardian Settings Map v1")
print("Backup:",backup)
